export type exportElementsResponse200 = {
  data: ElementPage;
  status: 200;
};

export type exportElementsResponseSuccess = exportElementsResponse200 & {
  headers: Headers;
};
export type exportElementsResponse = exportElementsResponseSuccess;

export const getExportElementsUrl = () => {
  return `/elements/export`;
};

export const exportElements = async (
  exportRequest: ExportRequest,
  options?: RequestInit,
): Promise<exportElementsResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  const res = await fetch(getExportElementsUrl(), {
    ...options,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(exportRequest),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: exportElementsResponse['data'] = body ? JSON.parse(body) : {};
  return {
    data,
    status: res.status,
    headers: res.headers,
  } as exportElementsResponse;
};

export const getExportElementsMutationKey = () => ['exportElements'] as const;

export const getExportElementsMutationOptions = <
  TError = unknown,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof exportElements>>,
    TError,
    ExportElementsMutationVariables,
    TContext
  >;
  fetch?: RequestInit;
}): UseMutationOptions<
  Awaited<ReturnType<typeof exportElements>>,
  TError,
  ExportElementsMutationVariables,
  TContext
> => {
  const mutationKey = getExportElementsMutationKey();
  const { mutation: mutationOptions, fetch: fetchOptions } = options
    ? options.mutation &&
      'mutationKey' in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, fetch: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof exportElements>>,
    ExportElementsMutationVariables
  > = (props) => {
    const { data } = props ?? {};

    return exportElements(data, fetchOptions);
  };

  return { mutationFn, ...mutationOptions };
};

